import{_ as i,o as t,c as l,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-06-14","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-06-14","date":"2023-06-14T00:00:00.000Z","updated":"2023-07-03T00:00:00.000Z","tags":["Ceph","RGW","MD5优化","E","Tag计算","多重Zipper后端","OLH修复","通知重试机制","测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-14.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-14.md","lastUpdated":1780460162000}'),o={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-06-14.md"};function r(n,e,a,_,s,g){return t(),l("div",null,[...e[0]||(e[0]=[p("<p>在2023年6月14日的Ceph RGW重构会议中，Ceph研发团队成员讨论了多个技术优化和功能改进议题。以下是会议的主要内容和决定事项：</p><ol><li><p><strong>MD5优化与E-Tag计算</strong>：</p><ul><li>讨论了MD5计算效率的问题，并尝试了XMD和向量化方法，预计可提升5倍速度。</li><li>决定尝试AC+库的AVX2实现进行实验，以减少CPU使用率。</li><li>后续行动：联系Mark进行评估，并进行性能测试。</li></ul></li><li><p><strong>多重Zipper后端与过滤器</strong>：</p><ul><li>讨论了在D4和d3n缓存工作中使用多重过滤器的问题。</li><li>决定定义每种驱动程序的JSON格式，并创建相应的工厂函数。</li><li>后续行动：Ali将开始研究并实现这一功能。</li></ul></li><li><p><strong>OLH修复</strong>：</p><ul><li>Corey更新了关于OLH修复的PR，解决了并发问题和遗留的索引条目问题。</li><li>决定进一步讨论如何进行更全面的并发测试。</li><li>后续行动：Corey将继续完善PR，并探索更多的测试方法。</li></ul></li><li><p><strong>通知重试机制</strong>：</p><ul><li>Krunal讨论了通知重试机制的改进。</li><li>决定进一步讨论如何限制FIFO的大小，以及是否需要设置重试次数或时间限制。</li><li>后续行动：Krunal将开始转换工作，并继续讨论设计细节。</li></ul></li></ol><p>会议还涉及了数据同步公平性的测试问题，目前仍在解决一些崩溃和边缘案例。</p><p>会议总结：会议涵盖了多个技术优化和功能改进的讨论，团队成员将根据讨论结果进行后续的开发和测试工作。</p>",4)])])}const u=i(o,[["render",r]]);export{d as __pageData,u as default};
